import java.util.*;

class Solution {
    public int countPairs(int[] nums, int target) {
        Map<Integer, Integer> seen = new HashMap<>();
        int pairs = 0;
        for (int x : nums) {
            pairs += seen.getOrDefault(target - x, 0);
            seen.put(x, seen.getOrDefault(x, 0) + 1);
        }
        return pairs;
    }
}
